import os, sqlite3, statistics, re, json
from pathlib import Path

db=Path(os.environ['TRACKER_FIELD_DB']); con=sqlite3.connect(f'file:{db}?mode=ro',uri=True); con.row_factory=sqlite3.Row
def cols(t): return [r[1] for r in con.execute(f'pragma table_info(\"{t}\")')]
def pick(cs,opts):
 m={c.lower():c for c in cs}
 for o in opts:
  if o.lower() in m:return m[o.lower()]
 return None
def q(s): return '"'+s.replace('"','""')+'"'
def hx(s):
 if not s:return b''
 z=re.sub(r'[^0-9A-Fa-f]','',str(s))
 if len(z)%2:z=z[:-1]
 try:return bytes.fromhex(z)
 except:return b''
def findmy_key(payload):
 b=hx(payload); i=0
 while i+1<len(b):
  t=b[i]; ln=b[i+1]
  if i+2+ln>len(b): break
  v=b[i+2:i+2+ln]
  if t==0x12 and len(v)>=2:return bytes(v[1:])
  i+=2+ln
 return None
def model_id(payload):
 b=hx(payload); return ((b[0]<<8)|b[1]) if len(b)>=2 else None
def med(xs):return round(statistics.median(xs),1) if xs else None

sc=cols('signal_samples'); dc=cols('devices'); fc=cols('follow_me_observations')
sfp=pick(sc,['deviceFingerprint','fingerprint']); st=pick(sc,['timestamp']); sr=pick(sc,['rssi']); smid=pick(sc,['manufacturerId']); smhex=pick(sc,['manufacturerDataHex']); sn=pick(sc,['deviceName']); sv=pick(sc,['vendorName']); sdt=pick(sc,['deviceType']); sb=pick(sc,['beaconType'])
dfp=pick(dc,['fingerprint']); dname=pick(dc,['lastDeviceName']); dv=pick(dc,['vendorName']); dm=pick(dc,['predictedModel']); ddt=pick(dc,['deviceType']); dbcn=pick(dc,['beaconType']); dscore=pick(dc,['followingScore']); dstatus=pick(dc,['trackingStatus'])
mx=con.execute(f'SELECT MAX({q(st)}) FROM signal_samples').fetchone()[0]; start=mx-3*60*60*1000
print('FOLLOW_COLUMNS',','.join(fc))
# Derive recent movement segments from persisted follow-me observations if possible.
ft=pick(fc,['timestamp']); fm=pick(fc,['userMoved','followMeUserMoved']); segments=[]
if ft and fm:
 ts=[int(r[0]) for r in con.execute(f'SELECT {q(ft)} FROM follow_me_observations WHERE {q(fm)}=1 AND {q(ft)}>=? ORDER BY {q(ft)}',(start,))]
 if ts:
  a=p=ts[0]; n=1
  for x in ts[1:]:
   if x-p>180000:
    segments.append((a,p,n)); a=x; n=0
   p=x; n+=1
  segments.append((a,p,n))
for i,(a,b,n) in enumerate(segments[-5:],1): print('MOVE_SEG',i,'durationMin',round((b-a)/60000,1),'events',n,'ageEndMin',round((mx-b)/60000,1))
# Prefer longest recent movement segment >=5 min; otherwise use 90 min ending at max.
valid=[s for s in segments if s[1]-s[0]>=5*60000]
walk=max(valid,key=lambda x:x[1]-x[0]) if valid else (mx-90*60000,mx,0)
wa,wb,_=walk; print('WALK_WINDOW','durationMin',round((wb-wa)/60000,1),'ageEndMin',round((mx-wb)/60000,1))

def devmeta(fp):
 r=con.execute(f'SELECT * FROM devices WHERE {q(dfp)}=?',(fp,)).fetchone()
 if not r:return {}
 return {'name':str(r[dname] or '') if dname else '', 'vendor':str(r[dv] or '') if dv else '', 'model':str(r[dm] or '') if dm else '', 'type':str(r[ddt] or '') if ddt else '', 'beacon':str(r[dbcn] or '') if dbcn else '', 'score':float(r[dscore] or 0) if dscore else 0, 'status':str(r[dstatus] or '') if dstatus else ''}
def stats(rows):
 tt=[int(r[st]) for r in rows]; rr=[int(r[sr]) for r in rows if r[sr] is not None]; bins={int((t-wa)//30000) for t in tt if wa<=t<=wb}; total=max(1,int((wb-wa)//30000)+1)
 return {'samples':len(tt),'spanMin':round((max(tt)-min(tt))/60000,1) if tt else 0,'medianRssi':med(rr),'walkCoverage':round(len(bins)/total,3),'firstAgeFromWalkMin':round((min(tt)-wa)/60000,1) if tt else None,'lastBeforeWalkEndMin':round((wb-max(tt))/60000,1) if tt else None}
rows=list(con.execute(f'SELECT * FROM signal_samples WHERE {q(st)}>=? ORDER BY {q(st)}',(start,)))
# Garmin company ID 0x0087 and text fallback.
groups={}
for r in rows:
 text=' '.join(str(r[c] or '') for c in [sn,sv,sdt,sb] if c).lower(); mid=r[smid] if smid else None
 if mid==0x87 or 'garmin' in text or 'forerunner' in text:
  groups.setdefault(str(r[sfp]),[]).append(r)
for i,(fp,rs) in enumerate(sorted(groups.items(),key=lambda kv:len(kv[1]),reverse=True)[:12],1):
 m=devmeta(fp); mids=sorted({model_id(r[smhex]) for r in rs if smhex and model_id(r[smhex]) is not None})
 print('GARMIN',json.dumps({'id':f'G{i:02d}',**m,**stats(rs),'modelIds':[f'0x{x:04X}' for x in mids[:6]]},sort_keys=True))
# Sony candidates, ranked by coverage in chosen movement window.
sg={}
for r in rows:
 text=' '.join(str(r[c] or '') for c in [sn,sv,sdt,sb] if c).lower()
 if 'sony' in text or 'wf-' in text or 'wh-' in text or 'le_wf' in text:
  sg.setdefault(str(r[sfp]),[]).append(r)
sony=[]
for fp,rs in sg.items(): sony.append((stats(rs)['walkCoverage'],len(rs),fp,rs))
for i,(_,_,fp,rs) in enumerate(sorted(sony,reverse=True)[:12],1): print('SONY',json.dumps({'id':f'S{i:02d}',**devmeta(fp),**stats(rs)},sort_keys=True))
# Apple Find My key groups from Continuity TLV 0x12. Never print payload/key/fingerprint.
kg={}
for r in rows:
 if smid and r[smid]!=76: continue
 key=findmy_key(r[smhex] if smhex else None)
 if key is not None: kg.setdefault(key,[]).append(r)
items=[]
for key,rs in kg.items():
 s=stats(rs); fps=len({str(r[sfp]) for r in rs}); m=devmeta(str(rs[-1][sfp]));
 # quality favors movement coverage, persistence, strong nearby signal, and multiple samples.
 strength=max(0,min(1,((-55)-(s['medianRssi'] or -100))/30+1)) if s['medianRssi'] is not None else 0
 quality=100*(0.55*s['walkCoverage']+0.20*min(1,s['samples']/30)+0.15*min(1,s['spanMin']/20)+0.10*strength)
 items.append((quality,key,rs,s,fps,m))
private={}
for i,(quality,key,rs,s,fps,m) in enumerate(sorted(items,reverse=True)[:25],1):
 label=f'K{i:02d}'; private[label]=key.hex(); print('FINDMY_KEY',json.dumps({'id':label,'quality':round(quality,1),'fingerprints':fps,**m,**s},sort_keys=True))
(db.parent/'findmy-key-map-v89.json').write_text(json.dumps(private,indent=2))
print('FINDMY_KEYS_RECENT',len(kg))
# Top tracker-ish fingerprints independent of Apple key parse.
tg={}
for r in rows:
 text=' '.join(str(r[c] or '') for c in [sn,sv,sdt,sb] if c).lower()
 if any(x in text for x in ['find my','findmy','airtag','tracker','smarttag','tile']) or str(r[sdt] or '').upper() in {'TAG','TRACKER','AIRTAG','TILE','SAMSUNG_TAG'}:
  tg.setdefault(str(r[sfp]),[]).append(r)
rank=[]
for fp,rs in tg.items():
 s=stats(rs); rank.append((s['walkCoverage'],len(rs),fp,rs,s))
for i,(_,_,fp,rs,s) in enumerate(sorted(rank,reverse=True)[:20],1): print('TRACKER_FP',json.dumps({'id':f'T{i:02d}',**devmeta(fp),**s},sort_keys=True))
